// A coarse level of a raw cube, sampling the centre post of each step x step cell.
export function stridedLevel(read, width, height, step) {
  const w = Math.ceil(width / step);
  const h = Math.ceil(height / step);
  const out = new Float32Array(w * h);
  for (let j = 0; j < h; j += 1) {
    const y = j * step + Math.floor(step / 2);
    for (let i = 0; i < w; i += 1) {
      const x = i * step + Math.floor(step / 2);
      out[j * w + i] = read(x, y);
    }
  }
  return { width: w, height: h, data: out };
}
